// AUTO-GENERATED by tools/director.py — do not hand-edit.
// sets/room.js — the one location. Night. One pendant lamp is the only bright thing.
// Screen direction: MAX frame-LEFT facing right, JAKE frame-RIGHT facing left. Never crossed.
import { E, V, mood, layer, backdrop, seg, poly, circle, linGrad, glow, shade, mix } from '/engine/core.js';
import * as FX from '/engine/fx2d.js';

export const GROUND = () => E.H * V(0.80, 0.70);
export const LAMP = () => [E.W * 0.5 + V(70, 40), E.H * V(0.17, 0.13)];
export const SEATS = () => ({ left: E.W * 0.30, right: E.W * 0.70 });
export const DOOR_X = () => E.W * 0.90;
export const COUNTER_Y = () => GROUND() - V(122, 112);

// One definition, used by the set AND any repaint after the cast — two copies is
// how a seam appears at the counter edge.
function counterPanel(g, GY, M, dark) {
  const ch = V(122, 112), cy = GY - ch, x = -V(80, 60), w = V(900, 600);
  const [lx] = LAMP();
  g.fillStyle = shade(dark, 0.05); g.fillRect(x, cy, w, ch + 46);
  g.fillStyle = linGrad(g, 0, cy, 0, cy + ch, [[0, shade(dark, 0.26)], [1, shade(dark, 0.02)]]);
  g.fillRect(x, cy, w, ch);
  g.fillStyle = shade(dark, 0.52); g.fillRect(x, cy, w, 14);
  glow(g, lx, cy + ch * 0.55, V(430, 340), M.practical, 0.055);
}

export function room(g, t, cam = {}, o = {}) {
  const M = mood(o.moodName || 'midnight'), GY = GROUND(), CX = E.W / 2;
  const wall = shade(M.wall, -0.35), dark = shade(M.wall, -0.66);
  const [lx, ly] = LAMP();

  // plane 1 · sky, stars, moon (slowest parallax)
  layer(g, cam, 0.14, (g) => {
    backdrop(g, M.sky);
    FX.stars(g, t, { count: 26, area: [0, 0, E.W, E.H * 0.5], color: '#dfe8ff' });
    FX.moon(g, CX - V(700, 330), E.H * V(0.15, 0.10), V(44, 40));
  });

  // plane 2 · back wall, window, god rays, door
  layer(g, cam, 0.5, (g) => {
    // the top of the wall falls away into shadow — an evenly-lit flat field is
    // what makes a wide read as an illustration instead of a room at night
    g.fillStyle = linGrad(g, 0, 0, 0, GY, [[0, shade(M.wall, -0.72)], [0.45, wall], [1, dark]]);
    g.fillRect(-E.W, -E.H, E.W * 4, GY + E.H);
    g.fillStyle = shade(dark, 0.16); g.fillRect(-E.W, GY - V(26, 22), E.W * 4, V(26, 22));  // baseboard

    const wx = CX - V(880, 400), wy = E.H * V(0.13, 0.09), ww = V(340, 250), wh = V(300, 330);
    FX.windowFrame(g, { x: wx, y: wy, w: ww, h: wh, cols: 2, rows: 2, frame: dark, bar: 8 }, (g, x, y, w, h) => {
      g.fillStyle = linGrad(g, 0, y, 0, y + h, [[0, mix(M.sky[1], '#1d2440', 0.55)], [1, M.sky[0]]]);
      g.fillRect(x, y, w, h);
    });
    glow(g, wx + ww / 2, wy + wh / 2, V(400, 360), '#8fa8d8', 0.08);
    FX.godRays(g, wx + ww / 2, wy + wh / 2, { count: 6, len: V(760, 800), spread: 0.4, color: '#9fb6e0', a: 0.05, angle: 1.22 });

    // a clock on the wall: the title is a time, so the room should agree with it
    FX.clock(g, CX + V(430, 210), E.H * V(0.20, 0.135), V(58, 46), 3 * 3600,
             { face: shade(M.wall, 0.30), ink: shade(dark, -0.25), red: '#c04a3a' });
    glow(g, CX + V(430, 210), E.H * V(0.20, 0.135), V(150, 120), '#8fa8d8', 0.05);

    const dw = V(230, 190), dh = V(430, 520), dx = DOOR_X();
    FX.door(g, { x: dx - dw / 2, y: GY, w: dw, h: dh, color: shade(dark, -0.15), open: o.doorOpen || 0, light: '#2a3554' });
    g.strokeStyle = shade(dark, 0.22); g.lineWidth = 7;
    g.strokeRect(dx - dw / 2, GY - dh, dw, dh);
    circle(g, dx - dw * 0.32, GY - dh * 0.46, V(11, 9), '#c9b48a');
  });

  // plane 3 · counter, floor, pendant lamp, floor pool
  layer(g, cam, 0.86, (g) => {
    counterPanel(g, GY, M, dark);
    g.fillStyle = linGrad(g, 0, GY, 0, GY + 460, [[0, shade(M.floor, -0.05)], [1, shade(M.dark, -0.32)]]);
    g.fillRect(-E.W, GY, E.W * 4, E.H * 2);
    FX.floorLines(g, GY, GY + 470, 'rgba(0,0,0,.3)', 0.085);

    seg(g, [[lx, 0], [lx, ly]], 6, dark);
    poly(g, [[lx - 52, ly], [lx + 52, ly], [lx + 32, ly + 40], [lx - 32, ly + 40]], shade(dark, 0.24));
    glow(g, lx, ly + 46, V(470, 570), M.practical, 0.52);
    FX.lightCone(g, lx, ly + 46, { angle: Math.PI / 2, spread: 0.42, len: COUNTER_Y() - ly, color: M.practical, a: 0.10 });
    FX.pool(g, lx, GY, V(330, 250), V(58, 44), M.practical, 0.20);
  });

  return { GY, M, seats: SEATS(), counterY: COUNTER_Y(), lamp: [lx, ly], doorX: DOOR_X() };
}
